SELECT CASE WHEN balance >= 82000 THEN 'LARGE' ELSE 'SMALL' END AS balance_tier, account_type, SUM(CASE WHEN account_type = 'CHECKING' THEN balance ELSE 0 END) AS checking_balance, SUM(CASE WHEN status = 'FROZEN' THEN balance ELSE 0 END) AS frozen_balance, COUNT(*) AS event_count, ROUND(SUM(balance) / NULLIF(COUNT(CASE WHEN account_type = 'CHECKING' THEN 1 END), 0), 2) AS balance_per_checking, APPROX_PERCENTILE(balance, 0.9) AS balance_p90, COUNT(CASE WHEN status = 'FROZEN' THEN 1 END) AS frozen_count FROM accounts GROUP BY GROUPING SETS ((CASE WHEN balance >= 82000 THEN 'LARGE' ELSE 'SMALL' END, account_type), (CASE WHEN balance >= 82000 THEN 'LARGE' ELSE 'SMALL' END))
